window.MeowWebBundle={"wxml":"<view class=\"app-shell\">\n  <view class=\"status-space\" style=\"height:{{statusBar}}px\"></view>\n  <view class=\"app-header\"><view class=\"brand\"><view class=\"brand-icon\"><image src=\"/assets/paw.png\" /></view><text>喵喵账本</text><view class=\"brand-dot\"></view></view><button class=\"install-button\" bindtap=\"installHelp\"><image src=\"/assets/plus.png\"/><text>放到桌面</text></button></view>\n  <view class=\"account-switch\" aria-label=\"选择账本\"><button class=\"account-option {{account === 'personal' ? 'active' : ''}}\" data-account=\"personal\" bindtap=\"switchAccount\"><image src=\"/assets/cat.png\"/><text>个人消费</text></button><button class=\"account-option {{account === 'public' ? 'active' : ''}}\" data-account=\"public\" bindtap=\"switchAccount\"><image src=\"/assets/book.png\"/><text>公账</text></button></view>\n  <view class=\"main\">\n    <view class=\"page-title-row\"><view><view class=\"eyebrow\">{{account === 'public' ? (tab === 'home' ? 'PUBLIC REIMBURSEMENT' : tab === 'bills' ? 'CLASSIFY EVERY PURCHASE' : tab === 'stats' ? 'CHECK THE MONTH' : 'LEDGER SETTINGS') : (tab === 'home' ? 'A LITTLE EVERY DAY' : tab === 'bills' ? 'LIFE IN LITTLE NUMBERS' : tab === 'stats' ? 'KNOW YOUR LITTLE HABITS' : 'YOUR COZY CORNER')}}</view><view class=\"page-title\">{{account === 'public' ? (tab === 'home' ? '公账报销，清清楚楚' : tab === 'bills' ? '每一笔，都归好位' : tab === 'stats' ? '本月公账，一眼核对' : '公账设置') : (tab === 'home' ? '把日子，记得可爱一点' : tab === 'bills' ? '每一笔，都算数' : tab === 'stats' ? '看看钱都去哪儿了' : '我的小小账本')}}<text class=\"title-dot\">.</text></view></view></view>\n    <view class=\"month-row\"><view class=\"month-switch\"><view class=\"month-arrow\" bindtap=\"previousMonth\"><image src=\"/assets/arrowLeft.png\"/></view><picker mode=\"date\" fields=\"month\" value=\"{{month}}\" start=\"2000-01\" end=\"2100-12\" bindchange=\"changeMonth\"><view class=\"month-label\">{{vm.monthLabel}}<image src=\"/assets/chevron.png\"/></view></picker><view class=\"month-arrow\" bindtap=\"nextMonth\"><image src=\"/assets/arrow.png\"/></view></view><view class=\"local-badge\"><view></view>仅存本机</view></view>\n    <block wx:if=\"{{tab === 'home'}}\">\n      <view wx:if=\"{{account === 'public'}}\" class=\"hero-card public-hero-card\">\n        <view class=\"public-hero-top\"><view><text>本月可报销支出</text><view class=\"public-hero-period\">{{vm.monthLabel}} · 上半月 / 下半月自动分表</view></view><view class=\"public-hero-stamp\">公账</view></view>\n        <view class=\"hero-amount public-hero-amount\"><text>¥</text>{{vm.expenseText}}</view>\n        <view class=\"public-hero-halves\"><view><text>1–15 日</text><b>¥ {{publicMonthSummary.firstHalf.amountText}}</b><small>{{publicMonthSummary.firstHalf.count}} 笔</small></view><view><text>16 日起</text><b>¥ {{publicMonthSummary.secondHalf.amountText}}</b><small>{{publicMonthSummary.secondHalf.count}} 笔</small></view><view class=\"public-hero-balance\"><text>本月收入</text><b>¥ {{vm.incomeText}}</b><small>不计入报销</small></view></view>\n      </view>\n      <view wx:else=\"\" class=\"hero-card\"><view class=\"hero-copy\"><view class=\"hero-label\">本月支出 <view class=\"tiny-dot\"></view></view><view class=\"hero-amount\"><text>¥</text>{{vm.expenseText}}</view><view class=\"hero-message\">认真生活的每一笔，都值得记录。</view></view><image class=\"hero-cat\" src=\"/assets/mascot.png\" mode=\"aspectFit\"/><view class=\"hero-bottom\"><view><text class=\"hero-small-label\">本月收入</text><view class=\"hero-sub-amount\"><text>¥</text> {{vm.incomeText}}</view></view><view class=\"hero-divider\"></view><view><text class=\"hero-small-label\">本月结余</text><view class=\"hero-sub-amount\"><text>¥</text> {{vm.balanceText}}</view></view><view class=\"hero-bottom-paw\"><image src=\"/assets/paw.png\"/></view></view></view>\n      <view wx:if=\"{{account === 'public'}}\" class=\"public-overview-card\"><view class=\"public-overview-head\"><view><text>报销拆分</text><view>同一天可以同时有普通采购和酒水</view></view><button data-filter=\"all\" bindtap=\"openPublicFilter\">查看明细<image src=\"/assets/arrow.png\"/></button></view><view class=\"public-overview-grid\"><view class=\"public-group-card general\"><text><i class=\"public-dot general\"></i>普通采购</text><view>¥ {{publicMonthSummary.general.amountText}}</view><small>{{publicMonthSummary.general.count}} 笔 · 食材 / 耗材 / 其他 / 兼职</small></view><view class=\"public-group-card drinks\"><text><i class=\"public-dot drinks\"></i>酒水</text><view>¥ {{publicMonthSummary.drinks.amountText}}</view><small>{{publicMonthSummary.drinks.count}} 笔 · 单独导出</small></view></view><button class=\"public-export-link\" bindtap=\"exportBook\"><image src=\"/assets/download.png\"/><text>导出 {{vm.monthLabel}}所在年份的两份 Excel</text><image src=\"/assets/arrow.png\"/></button></view>\n      <view wx:if=\"{{account === 'public'}}\" class=\"public-quick-actions\"><view><text>快速记一笔</text><small>先选报销单，事项仍会自动归类</small></view><button data-group=\"general\" bindtap=\"addPublicEntry\"><image src=\"/assets/bag.png\"/><text>普通采购</text></button><button data-group=\"drinks\" bindtap=\"addPublicEntry\"><image src=\"/assets/cup.png\"/><text>酒水</text></button></view>\n      <block wx:if=\"{{account !== 'public'}}\">\n      <view class=\"budget-card\" bindtap=\"openBudget\"><view class=\"budget-top\"><view class=\"budget-title\"><image src=\"/assets/wallet.png\"/><text>{{accountName}}预算</text></view><view class=\"budget-remaining {{vm.overBudget ? 'negative' : ''}}\"><block wx:if=\"{{vm.hasBudget}}\">{{vm.overBudget ? '已超支' : '还可花'}} <text>¥ {{vm.remainingText}}</text></block><text wx:else=\"\">设置预算 ›</text><image src=\"/assets/arrow.png\"/></view></view><view class=\"progress-track\"><view class=\"progress-fill {{vm.overBudget ? 'over' : ''}}\" style=\"width:{{vm.budgetPercent}}%\"></view></view><view class=\"budget-meta\"><text>{{vm.hasBudget ? '已用 ' + vm.budgetPercent + '%' : '尚未设置预算'}}</text><text>{{vm.hasBudget ? '月预算 ¥ ' + vm.budgetText : '点击设置当前账本预算'}}</text></view></view>\n      <view class=\"section-heading\"><view>最近账单<text class=\"section-count\">{{vm.count}} 笔</text></view><view class=\"text-link\" bindtap=\"allBills\">查看全部<image src=\"/assets/arrow.png\"/></view></view>\n      <view wx:if=\"{{vm.groups.length === 0}}\" class=\"empty-state\"><image src=\"/assets/empty-cat.png\"/><view class=\"empty-title\">{{vm.isCurrentMonth ? '今天的故事，从第一笔开始' : '这个月，账本还是空白的'}} </view><view class=\"empty-desc\">点下方「＋」，收好生活的小细节</view><button class=\"small-button\" bindtap=\"addEntry\">记下第一笔</button></view>\n      <view class=\"bill-groups\"><block wx:for=\"{{vm.recentGroups}}\" wx:key=\"date\" wx:for-item=\"group\"><view class=\"day-heading\"><view><text class=\"day-label\">{{group.label}}</text><text class=\"day-week\">{{group.weekday}}</text></view><view class=\"day-total\"><text wx:if=\"{{group.expense}}\">支出 {{group.expenseText}}</text><text wx:if=\"{{group.income}}\"> 收入 {{group.incomeText}}</text></view></view><view class=\"bill-card {{account === 'public' ? 'public-bill-card' : ''}}\"><view wx:for=\"{{group.rows}}\" wx:key=\"id\" class=\"bill-row {{account === 'public' &amp;&amp; item.type === 'expense' ? 'public-bill-row' : ''}}\" data-id=\"{{item.id}}\" bindtap=\"editEntry\"><view class=\"category-icon\" style=\"background:{{item.color}}\"><image src=\"/assets/{{item.icon}}.png\"/></view><view class=\"bill-info\"><view wx:if=\"{{account === 'public' &amp;&amp; item.type === 'expense'}}\" class=\"report-row-title\"><text class=\"report-name {{item.reportGroup}}\">{{item.reportGroupName}}</text><text class=\"report-column\">{{item.reportColumnName}}</text></view><view wx:else=\"\" class=\"bill-category\">{{item.categoryName}}</view><view class=\"bill-note\">{{item.note || '生活里的小记录'}}</view><view wx:if=\"{{account === 'public' &amp;&amp; item.spec}}\" class=\"bill-spec\">规格 {{item.spec}}</view></view><view class=\"bill-amount {{item.type === 'income' ? 'income' : ''}}\">{{item.sign}}{{item.displayAmount}}</view></view></view></block></view>\n      <view class=\"daily-note\"><image src=\"/assets/paw.png\"/><text>不必每一笔都完美，记下来就很棒。</text></view>\n      </block>\n    </block>\n    <block wx:elif=\"{{tab === 'bills'}}\">\n      <view class=\"mini-summary\"><view><text>本月支出</text><view>¥ {{vm.expenseText}}</view></view><view><text>本月收入</text><view class=\"income\">¥ {{vm.incomeText}}</view></view></view>\n      <view wx:if=\"{{account === 'public'}}\" class=\"public-split-summary\"><view class=\"general\"><text>普通采购 · {{publicMonthSummary.general.count}} 笔</text><b>¥ {{publicMonthSummary.general.amountText}}</b></view><view class=\"drinks\"><text>酒水 · {{publicMonthSummary.drinks.count}} 笔</text><b>¥ {{publicMonthSummary.drinks.amountText}}</b></view><button bindtap=\"exportBook\"><image src=\"/assets/download.png\"/><text>导出 Excel</text></button></view>\n      <view wx:if=\"{{account === 'public'}}\" class=\"public-column-strip bills-column-strip\"><view><text>食材</text><b>{{publicMonthSummary.columns.food.amountText}}</b></view><view><text>耗材</text><b>{{publicMonthSummary.columns.supplies.amountText}}</b></view><view><text>其他</text><b>{{publicMonthSummary.columns.other.amountText}}</b></view><view><text>兼职</text><b>{{publicMonthSummary.columns.parttime.amountText}}</b></view></view>\n      <view class=\"search-box\"><image src=\"/assets/search.png\"/><input value=\"{{query}}\" placeholder=\"搜索分类或备注\" bindinput=\"search\" maxlength=\"40\"/></view>\n      <view class=\"bill-tools\"><view class=\"filter-row\"><block wx:if=\"{{account === 'public'}}\"><view class=\"filter {{filter === 'all' ? 'active' : ''}}\" data-filter=\"all\" bindtap=\"setFilter\">全部</view><view class=\"filter {{filter === 'general' ? 'active' : ''}}\" data-filter=\"general\" bindtap=\"setFilter\">普通采购</view><view class=\"filter {{filter === 'drinks' ? 'active' : ''}}\" data-filter=\"drinks\" bindtap=\"setFilter\">酒水</view><view class=\"filter {{filter === 'income' ? 'active' : ''}}\" data-filter=\"income\" bindtap=\"setFilter\">收入</view></block><block wx:else=\"\"><view class=\"filter {{filter === 'all' ? 'active' : ''}}\" data-filter=\"all\" bindtap=\"setFilter\">全部账单</view><view class=\"filter {{filter === 'expense' ? 'active' : ''}}\" data-filter=\"expense\" bindtap=\"setFilter\">只看支出</view><view class=\"filter {{filter === 'income' ? 'active' : ''}}\" data-filter=\"income\" bindtap=\"setFilter\">只看收入</view></block></view><button class=\"batch-toggle {{batchMode ? 'active' : ''}}\" bindtap=\"toggleBatchMode\">{{batchMode ? '完成' : '批量管理'}}</button></view>\n      <view wx:if=\"{{batchMode}}\" class=\"batch-bar\"><button class=\"batch-select-all\" bindtap=\"selectAllVisible\">{{allVisibleSelected ? '取消全选' : '全选当前列表'}}</button><text>已选 {{selectedCount}} 笔</text><button class=\"batch-delete\" disabled=\"{{selectedCount === 0}}\" bindtap=\"batchDelete\">删除选中</button></view>\n      <view wx:if=\"{{vm.groups.length === 0}}\" class=\"empty-state\"><image src=\"/assets/empty-cat.png\"/><view class=\"empty-title\">{{query ? '没有找到这笔小记录' : '这里还没有账单喵'}} </view><view class=\"empty-desc\">{{query ? '换个关键词试试看' : '换个月份，或记下新的一笔'}}</view></view>\n      <view class=\"bill-groups\"><block wx:for=\"{{vm.groups}}\" wx:key=\"date\" wx:for-item=\"group\"><view class=\"day-heading\"><view><text class=\"day-label\">{{group.label}}</text><text class=\"day-week\">{{group.weekday}}</text></view><view class=\"day-total\"><text wx:if=\"{{group.expense}}\">支出 {{group.expenseText}}</text><text wx:if=\"{{group.income}}\"> 收入 {{group.incomeText}}</text></view></view><view class=\"bill-card {{batchMode ? 'batch-card' : ''}} {{account === 'public' ? 'public-bill-card' : ''}}\"><view wx:for=\"{{group.rows}}\" wx:key=\"id\" class=\"bill-row {{batchMode ? 'selecting' : ''}} {{item.selected ? 'selected' : ''}} {{account === 'public' &amp;&amp; item.type === 'expense' ? 'public-bill-row' : ''}}\" data-id=\"{{item.id}}\" bindtap=\"handleBillTap\"><view wx:if=\"{{batchMode}}\" class=\"select-check {{item.selected ? 'checked' : ''}}\"><image src=\"/assets/check.png\"/></view><view class=\"category-icon\" style=\"background:{{item.color}}\"><image src=\"/assets/{{item.icon}}.png\"/></view><view class=\"bill-info\"><view wx:if=\"{{account === 'public' &amp;&amp; item.type === 'expense'}}\" class=\"report-row-title\"><text class=\"report-name {{item.reportGroup}}\">{{item.reportGroupName}}</text><text class=\"report-column\">{{item.reportColumnName}}</text></view><view wx:else=\"\" class=\"bill-category\">{{item.categoryName}}</view><view class=\"bill-note\">{{item.note || '生活里的小记录'}}</view><view wx:if=\"{{account === 'public' &amp;&amp; item.spec}}\" class=\"bill-spec\">规格 {{item.spec}}</view></view><view class=\"bill-amount {{item.type === 'income' ? 'income' : ''}}\">{{item.sign}}{{item.displayAmount}}</view></view></view></block></view>\n    </block>\n    <block wx:elif=\"{{tab === 'stats'}}\">\n      <view class=\"stats-top\"><view class=\"stat-card\"><image src=\"/assets/bowl.png\"/><text>{{account === 'public' ? '公账本月支出' : '本月支出'}}</text><view>¥ {{vm.expenseText}}</view></view><view class=\"stat-card sage\"><image src=\"/assets/{{account === 'public' ? 'cup' : 'sun'}}.png\"/><text>{{account === 'public' ? '酒水' : '日均支出'}}</text><view>¥ {{account === 'public' ? publicMonthSummary.drinks.amountText : vm.dailyText}}</view></view></view>\n      <view wx:if=\"{{account === 'public'}}\" class=\"public-column-card\"><view class=\"public-column-card-head\"><view><text>报销金额列</text><small>与 Excel 的表头和金额保持一致</small></view><view>共 ¥ {{vm.expenseText}}</view></view><view class=\"public-column-card-grid\"><view class=\"food\"><text>食材</text><b>¥ {{publicMonthSummary.columns.food.amountText}}</b><small>{{publicMonthSummary.columns.food.count}} 笔</small></view><view class=\"supplies\"><text>耗材</text><b>¥ {{publicMonthSummary.columns.supplies.amountText}}</b><small>{{publicMonthSummary.columns.supplies.count}} 笔</small></view><view class=\"other\"><text>其他</text><b>¥ {{publicMonthSummary.columns.other.amountText}}</b><small>{{publicMonthSummary.columns.other.count}} 笔</small></view><view class=\"parttime\"><text>兼职</text><b>¥ {{publicMonthSummary.columns.parttime.amountText}}</b><small>{{publicMonthSummary.columns.parttime.count}} 笔</small></view></view></view>\n      <view class=\"chart-card\" wx:if=\"{{vm.isCurrentMonth}}\"><view class=\"section-heading\"><view>近 7 天支出</view><text class=\"subtle\">单位：元</text></view><view class=\"bar-chart\"><view wx:for=\"{{vm.week}}\" wx:key=\"date\" class=\"bar-column\"><view class=\"bar-value\">{{item.amount ? item.amountText : ''}}</view><view class=\"bar-track\"><view class=\"bar {{item.label === '今' ? 'today' : ''}}\" style=\"height:{{item.height}}%\"></view></view><text>{{item.label}}</text></view></view></view>\n      <view class=\"section-heading\"><view>{{account === 'public' ? '报销归类' : '支出排行榜'}}</view><text class=\"subtle\">{{account === 'public' ? '普通采购 / 酒水' : '按分类统计'}}</text></view><view wx:if=\"{{!vm.ranking.length}}\" class=\"empty-state\"><image src=\"/assets/empty-cat.png\"/><view class=\"empty-title\">还没有支出，继续保持喵</view><view class=\"empty-desc\">记录支出后，就能看到分类占比</view></view>\n      <view class=\"ranking-card\" wx:if=\"{{vm.ranking.length}}\"><view wx:for=\"{{vm.ranking}}\" wx:key=\"id\" class=\"rank-row\"><view class=\"category-icon\" style=\"background:{{item.color}}\"><image src=\"/assets/{{item.icon}}.png\"/></view><view class=\"rank-info\"><view class=\"rank-top\"><text>{{item.name}} <text class=\"rank-percent\">{{item.percent}}%</text></text><text>¥ {{item.amountText}}</text></view><view class=\"rank-track\"><view style=\"width:{{item.width}}%;background:{{item.color}}\"></view></view></view></view></view>\n      <view class=\"daily-note\"><image src=\"/assets/spark.png\"/><text>了解自己的小习惯，让每一笔更有方向。</text></view>\n    </block>\n    <block wx:else=\"\">\n      <view class=\"profile-card\"><view class=\"profile-avatar\"><image src=\"/assets/cat.png\"/></view><view><view class=\"profile-name\">认真生活的铲屎官</view><view class=\"profile-desc\">好好记账，慢慢变富。</view></view><view class=\"profile-flower\">✳</view></view>\n      <view class=\"profile-numbers\"><view><view>{{vm.totalCount}}<text> 笔</text></view><text>收好的小记录</text></view><view><view>{{vm.activeDays}}<text> 天</text></view><text>有记录的日子</text></view></view>\n      <view class=\"settings-card\"><view class=\"settings-row\" bindtap=\"openBudget\"><image src=\"/assets/wallet.png\"/><text>月度预算</text><view>¥ {{vm.budgetText}}</view><image class=\"chevron-icon\" src=\"/assets/arrow.png\"/></view><view class=\"settings-row\" bindtap=\"exportBook\"><image src=\"/assets/download.png\"/><text>导出当前账本</text><view>{{account === 'public' ? 'Excel 报销单' : 'CSV 表格'}}</view><image class=\"chevron-icon\" src=\"/assets/arrow.png\"/></view><view class=\"settings-row\" bindtap=\"showPrivacy\"><image src=\"/assets/shield.png\"/><text>数据与隐私</text><view>本地存储</view><image class=\"chevron-icon\" src=\"/assets/arrow.png\"/></view><view class=\"settings-row\" bindtap=\"clearBook\"><image src=\"/assets/trash.png\"/><text>清空当前账本</text><image class=\"chevron-icon\" src=\"/assets/arrow.png\"/></view></view>\n      <view class=\"profile-footer\"><image src=\"/assets/paw.png\"/><view>喵喵账本</view><text>给认真生活的你 · v{{version}}</text></view>\n    </block>\n  </view>\n  <view class=\"bottom-nav\"><view class=\"nav-item {{tab === 'home' ? 'selected' : ''}}\" data-tab=\"home\" bindtap=\"switchTab\"><image src=\"/assets/home.png\"/><text>首页</text><view class=\"nav-dot\"></view></view><view class=\"nav-item {{tab === 'bills' ? 'selected' : ''}}\" data-tab=\"bills\" bindtap=\"switchTab\"><image src=\"/assets/book.png\"/><text>账单</text><view class=\"nav-dot\"></view></view><button class=\"nav-add\" aria-label=\"记一笔\" hover-class=\"nav-add-pressed\" bindtap=\"addEntry\"><image src=\"/assets/plus.png\"/><text>记一笔</text></button><view class=\"nav-item {{tab === 'stats' ? 'selected' : ''}}\" data-tab=\"stats\" bindtap=\"switchTab\"><image src=\"/assets/chart.png\"/><text>统计</text><view class=\"nav-dot\"></view></view><view class=\"nav-item {{tab === 'mine' ? 'selected' : ''}}\" data-tab=\"mine\" bindtap=\"switchTab\"><image src=\"/assets/cat.png\"/><text>我的</text><view class=\"nav-dot\"></view></view></view>\n  <view wx:if=\"{{editor || budgetEditor || exportEditor}}\" class=\"modal-mask\" bindtap=\"closeEditor\"><view class=\"sheet\" catchtap=\"noop\"><view class=\"sheet-handle\"></view><view class=\"entry-account\"><image src=\"/assets/book.png\"/><text>当前账本 · {{accountName}}</text></view><view class=\"sheet-header\"><view class=\"sheet-title\"><text>{{exportEditor ? '导出公账报销单' : budgetEditor ? '给这个月定个小目标' : form.id ? (account === 'public' ? '调整这笔公账' : '编辑这笔小记录') : (account === 'public' ? '记一笔公账' : '记下生活的小事')}}</text><text wx:if=\"{{editor &amp;&amp; account === 'public' &amp;&amp; form.type === 'expense'}}\" class=\"report-hint {{reportKind.group}}\" role=\"status\" aria-live=\"polite\">{{reportHint}}</text></view><view class=\"close-button\" aria-label=\"关闭记账面板\" bindtap=\"closeEditor\"><image src=\"/assets/close.png\"/></view></view>\n    <block wx:if=\"{{exportEditor}}\">\n      <view class=\"export-help\">自动分成两个独立 Excel 文件，每个文件含 1月上、1月下至 12月下，共 24 张报销单。</view>\n      <view class=\"export-year\"><button aria-label=\"上一年\" data-offset=\"-1\" bindtap=\"changeExportYear\">‹</button><text>{{exportYear}} 年</text><button aria-label=\"下一年\" data-offset=\"1\" bindtap=\"changeExportYear\">›</button></view>\n      <view class=\"export-summary\"><view><text>普通采购</text><view>{{reportSummary.general.count}} 笔 · ¥ {{reportSummary.general.amountText}}</view></view><view><text>酒水</text><view>{{reportSummary.drinks.count}} 笔 · ¥ {{reportSummary.drinks.amountText}}</view></view></view>\n      <view class=\"export-help\">1–15 日为上半月，16 日起为下半月。只导出所选年份的公账支出；收入不计入报销。现有记录也会自动识别，导出前可在记账面板调整分类。</view>\n      <button class=\"primary-button export-download\" disabled=\"{{!reportsReady}}\" data-group=\"general\" bindtap=\"exportReport\">{{reportsReady ? '导出普通采购 Excel' : '正在准备报销单…'}}</button>\n      <button class=\"primary-button export-download secondary-export\" disabled=\"{{!reportsReady}}\" data-group=\"drinks\" bindtap=\"exportReport\">导出酒水 Excel</button>\n      <button class=\"csv-export\" bindtap=\"exportCsv\">导出完整流水 CSV（含收入，所有年份）</button>\n    </block>\n    <block wx:if=\"{{editor}}\">\n      <view class=\"type-switch\"><view class=\"{{form.type === 'expense' ? 'active' : ''}}\" data-type=\"expense\" bindtap=\"setType\">{{account === 'public' ? '支出 · 计入报销' : '支出'}}</view><view class=\"{{form.type === 'income' ? 'active' : ''}}\" data-type=\"income\" bindtap=\"setType\">{{account === 'public' ? '收入 · 不报销' : '收入'}}</view></view>\n      <view class=\"amount-input\"><text>¥</text><input type=\"digit\" value=\"{{form.amount}}\" placeholder=\"0.00\" maxlength=\"12\" bindinput=\"inputAmount\" adjust-position=\"{{true}}\"/></view>\n      <block wx:if=\"{{account === 'public'}}\">\n        <view wx:if=\"{{form.type === 'expense'}}\" class=\"report-fields\">\n          <view class=\"report-field-label\">报销单</view>\n          <view class=\"report-options report-group-options\" role=\"group\" aria-label=\"报销单分类\">\n            <button class=\"{{form.reportGroup === 'auto' ? 'active' : ''}}\" aria-pressed=\"{{form.reportGroup === 'auto'}}\" data-value=\"auto\" bindtap=\"setReportGroup\">自动识别</button>\n            <button class=\"{{form.reportGroup === 'general' ? 'active' : ''}}\" aria-pressed=\"{{form.reportGroup === 'general'}}\" data-value=\"general\" bindtap=\"setReportGroup\">普通采购</button>\n            <button class=\"{{form.reportGroup === 'drinks' ? 'active' : ''}}\" aria-pressed=\"{{form.reportGroup === 'drinks'}}\" data-value=\"drinks\" bindtap=\"setReportGroup\">酒水</button>\n          </view>\n          <view class=\"report-field-label\">金额列</view>\n          <view class=\"report-options report-column-options\" role=\"group\" aria-label=\"报销金额列\">\n            <button class=\"{{form.reportColumn === 'auto' ? 'active' : ''}}\" aria-pressed=\"{{form.reportColumn === 'auto'}}\" data-value=\"auto\" bindtap=\"setReportColumn\">自动</button>\n            <button class=\"{{form.reportColumn === 'food' ? 'active' : ''}}\" aria-pressed=\"{{form.reportColumn === 'food'}}\" data-value=\"food\" bindtap=\"setReportColumn\">食材</button>\n            <button class=\"{{form.reportColumn === 'supplies' ? 'active' : ''}}\" aria-pressed=\"{{form.reportColumn === 'supplies'}}\" data-value=\"supplies\" bindtap=\"setReportColumn\">耗材</button>\n            <button class=\"{{form.reportColumn === 'other' ? 'active' : ''}}\" aria-pressed=\"{{form.reportColumn === 'other'}}\" data-value=\"other\" bindtap=\"setReportColumn\">其他</button>\n            <button class=\"{{form.reportColumn === 'parttime' ? 'active' : ''}}\" aria-pressed=\"{{form.reportColumn === 'parttime'}}\" data-value=\"parttime\" bindtap=\"setReportColumn\">兼职</button>\n          </view>\n        </view>\n        <view class=\"public-entry-fields\"><view class=\"form-row public-note-row\"><image src=\"/assets/book.png\"/><text>事项</text><input value=\"{{form.note}}\" placeholder=\"如：无花果、獭祭45\" maxlength=\"40\" bindinput=\"inputNote\"/></view>\n        <picker class=\"date-picker\" mode=\"date\" value=\"{{form.date}}\" start=\"2000-01-01\" end=\"2100-12-31\" bindchange=\"inputDate\"><view class=\"form-row date-row\"><image src=\"/assets/calendar.png\"/><text>日期</text><view class=\"date-value\">{{form.date}}<text class=\"picker-arrow\">›</text></view></view></picker>\n        <view wx:if=\"{{form.type === 'expense' &amp;&amp; reportKind.group === 'drinks'}}\" class=\"form-row report-spec-row\"><image src=\"/assets/book.png\"/><text>规格</text><input value=\"{{form.spec}}\" placeholder=\"如：1800ml*2、48瓶（可不填）\" maxlength=\"80\" bindinput=\"inputSpec\"/></view></view>\n      </block>\n      <block wx:else=\"\">\n        <scroll-view class=\"category-scroll\" scroll-y=\"{{true}}\"><view class=\"category-grid\"><view wx:for=\"{{categories}}\" wx:key=\"id\" class=\"category-option {{form.category === item.id ? 'active' : ''}}\" data-id=\"{{item.id}}\" bindtap=\"setCategory\"><view class=\"category-icon\" style=\"background:{{form.category === item.id ? '#f8d86e' : item.color}}\"><image src=\"/assets/{{item.icon}}.png\"/></view><text>{{item.name}}</text></view></view></scroll-view>\n        <picker class=\"date-picker\" mode=\"date\" value=\"{{form.date}}\" start=\"2000-01-01\" end=\"2100-12-31\" bindchange=\"inputDate\"><view class=\"form-row date-row\"><image src=\"/assets/calendar.png\"/><text>日期</text><view class=\"date-value\">{{form.date}}<text class=\"picker-arrow\">›</text></view></view></picker>\n        <view class=\"form-row\"><image src=\"/assets/book.png\"/><text>备注</text><input value=\"{{form.note}}\" placeholder=\"为这笔记录加点故事\" maxlength=\"40\" bindinput=\"inputNote\"/></view>\n      </block>\n      <button class=\"primary-button\" bindtap=\"saveEntry\">{{form.id ? '保存修改' : account === 'public' ? '记入公账' : '记好啦'}}<image src=\"/assets/paw.png\"/></button>\n      <button wx:if=\"{{form.id}}\" class=\"delete-button\" bindtap=\"deleteEntry\">删除这笔记录</button><view wx:else=\"\" class=\"sheet-footnote\">小小一笔，也是在认真生活。</view>\n    </block>\n    <block wx:elif=\"{{budgetEditor}}\"><view class=\"budget-help\">每个月都留一点余地，给生活的小惊喜。<text>仅适用于{{accountName}}的每个月；输入 0 可取消预算。</text></view><view class=\"amount-input\"><text>¥</text><input type=\"digit\" value=\"{{budgetInput}}\" placeholder=\"0.00\" maxlength=\"12\" bindinput=\"inputBudget\"/></view><button class=\"primary-button\" bindtap=\"saveBudget\">就这样定啦<image src=\"/assets/check.png\"/></button></block>\n  </view></view>\n</view>\n","source":"const L = require('../../utils/ledger');\nPage({\n  data: { tab: 'home', statusBar: 24, month: L.today().slice(0,7), filter: 'all', query: '', vm: {}, categories: [], editor: false, budgetEditor: false, exportEditor: false, exportYear: 2026, reportSummary: {}, reportsReady: false, reportHint: '', reportKind: {}, form: {}, budgetInput: '', storageError: false, today: L.today(), version: '1.3.1 网页版', account: 'personal', accountName: '个人消费', batchMode: false, selectedIds: [], selectedCount: 0, allVisibleSelected: false, publicMonthSummary: {} },\n  onLoad() {\n    try { const info = typeof wx.getWindowInfo === 'function' ? wx.getWindowInfo() : wx.getSystemInfoSync(); this.setData({ statusBar: info.statusBarHeight || 24 }); } catch (_) {}\n    try {\n      const value = wx.getStorageSync(L.KEY);\n      this.workspace = L.normalizeWorkspace(value);\n      if (value && value.version === 1) wx.setStorageSync(L.KEY, this.workspace);\n    } catch (error) {\n      this.workspace = L.emptyWorkspace(); this.setData({ storageError: true });\n      wx.showModal({ title: '暂时无法读取账本', content: '请重新打开应用后再试。现有缓存不会被覆盖。', showCancel: false });\n    }\n    this.refresh();\n  },\n  onShow() {\n    if (!this.book) return;\n    this.setData({ tab: 'home', editor: false, budgetEditor: false, form: {}, month: L.today().slice(0,7), filter: 'all', query: '', batchMode: false, selectedIds: [], selectedCount: 0, allVisibleSelected: false });\n    this.refresh();\n  },\n  refresh() {\n    const account = this.workspace.activeAccount;\n    this.book = this.workspace.accounts[account];\n    const vm = L.summary(this.book, this.data.month, this.data.filter, this.data.query);\n    const monthSummary = this.publicMonthSummary();\n    if (account === 'public') vm.ranking = this.publicRanking(monthSummary);\n    vm.groups.forEach(group => group.rows.forEach(row => {\n      if (account === 'public') {\n        const kind = row.type === 'expense' ? L.reportClass(row) : null;\n        row.reportGroupName = kind ? kind.groupName : '';\n        row.reportColumnName = kind ? kind.columnName : '';\n        row.reportGroup = kind ? kind.group : '';\n        row.reportColumn = kind ? kind.column : '';\n      }\n      row.selected = this.data.selectedIds.includes(row.id);\n    }));\n    const visibleIds = vm.groups.reduce((ids, group) => ids.concat(group.rows.map(row => row.id)), []);\n    const selectedCount = vm.groups.reduce((count, group) => count + group.rows.filter(row => row.selected).length, 0);\n    const allVisibleSelected = visibleIds.length > 0 && visibleIds.every(id => this.data.selectedIds.includes(id));\n    this.setData({ account, accountName: L.accountNames[account], vm, publicMonthSummary: monthSummary, selectedCount, allVisibleSelected, today: L.today() });\n  },\n  publicMonthSummary() {\n    const rows = this.book.transactions.filter(row => row.date.slice(0, 7) === this.data.month && row.type === 'expense');\n    const summary = {\n      general: { count: 0, amount: 0, amountText: '0.00', share: 0 },\n      drinks: { count: 0, amount: 0, amountText: '0.00', share: 0 },\n      columns: {\n        food: { count: 0, amount: 0, amountText: '0.00' },\n        supplies: { count: 0, amount: 0, amountText: '0.00' },\n        other: { count: 0, amount: 0, amountText: '0.00' },\n        parttime: { count: 0, amount: 0, amountText: '0.00' }\n      },\n      firstHalf: { count: 0, amount: 0, amountText: '0.00' },\n      secondHalf: { count: 0, amount: 0, amountText: '0.00' },\n      total: 0,\n      totalText: '0.00',\n      count: rows.length\n    };\n    rows.forEach(row => {\n      const kind = L.reportClass(row);\n      const half = Number(row.date.slice(8)) <= 15 ? 'firstHalf' : 'secondHalf';\n      summary[kind.group].count += 1;\n      summary[kind.group].amount += row.amount;\n      summary.columns[kind.column].count += 1;\n      summary.columns[kind.column].amount += row.amount;\n      summary[half].count += 1;\n      summary[half].amount += row.amount;\n    });\n    summary.total = summary.general.amount + summary.drinks.amount;\n    ['general', 'drinks'].forEach(group => { summary[group].amountText = L.money(summary[group].amount); });\n    ['general', 'drinks'].forEach(group => { summary[group].share = summary.total ? Math.round(summary[group].amount / summary.total * 100) : 0; });\n    ['food', 'supplies', 'other', 'parttime'].forEach(column => { summary.columns[column].amountText = L.money(summary.columns[column].amount); });\n    ['firstHalf', 'secondHalf'].forEach(half => { summary[half].amountText = L.money(summary[half].amount); });\n    summary.totalText = L.money(summary.total);\n    return summary;\n  },\n  publicRanking(summary) {\n    const total = summary.total;\n    return [\n      { id: 'general', name: '普通采购', icon: 'bag', color: '#f7df9a', amount: summary.general.amount, amountText: summary.general.amountText },\n      { id: 'drinks', name: '酒水', icon: 'cup', color: '#dce8d3', amount: summary.drinks.amount, amountText: summary.drinks.amountText }\n    ].filter(item => item.amount > 0).map(item => Object.assign(item, { percent: total ? Math.round(item.amount / total * 100) : 0, width: total ? Math.max(3, item.amount / total * 100) : 0 })).sort((a, b) => b.amount - a.amount);\n  },\n  commit(book) {\n    if (this.data.storageError) { wx.showToast({ title: '请重新打开应用后再试', icon: 'none' }); return false; }\n    try {\n      const accounts = Object.assign({}, this.workspace.accounts, { [this.data.account]: L.normalize(book) });\n      const next = L.normalizeWorkspace(Object.assign({}, this.workspace, { accounts }));\n      wx.setStorageSync(L.KEY, next); this.workspace = next; this.refresh(); return true;\n    }\n    catch (_) { wx.showToast({ title: '保存失败，请检查设备存储空间', icon: 'none' }); return false; }\n  },\n  switchAccount(e) {\n    const account = e.currentTarget.dataset.account;\n    if (!Object.prototype.hasOwnProperty.call(L.accountNames, account) || account === this.data.account || this.data.editor || this.data.budgetEditor || this.data.exportEditor) return;\n    if (this.data.storageError) { wx.showToast({ title: '请重新打开应用后再试', icon: 'none' }); return; }\n    const next = Object.assign({}, this.workspace, { activeAccount: account });\n    try { wx.setStorageSync(L.KEY, next); }\n    catch (_) { wx.showToast({ title: '切换失败，请检查设备存储空间', icon: 'none' }); return; }\n    this.workspace = next;\n    this.setData({ filter: 'all', query: '', form: {}, batchMode: false, selectedIds: [], selectedCount: 0, allVisibleSelected: false }); this.refresh();\n    wx.pageScrollTo({ scrollTop: 0, duration: 150 });\n  },\n  switchTab(e) { this.setData({ tab: e.currentTarget.dataset.tab, filter: 'all', query: '', batchMode: false, selectedIds: [], selectedCount: 0, allVisibleSelected: false }); this.refresh(); wx.pageScrollTo({ scrollTop: 0, duration: 150 }); },\n  allBills() { this.setData({ tab: 'bills', filter: 'all', query: '', batchMode: false, selectedIds: [], selectedCount: 0, allVisibleSelected: false }); this.refresh(); wx.pageScrollTo({ scrollTop: 0, duration: 150 }); },\n  changeMonth(e) { this.setData({ month: e.detail.value.slice(0,7), batchMode: false, selectedIds: [], selectedCount: 0, allVisibleSelected: false }); this.refresh(); },\n  previousMonth() { this.setData({ month: L.shiftMonth(this.data.month, -1), batchMode: false, selectedIds: [], selectedCount: 0, allVisibleSelected: false }); this.refresh(); },\n  nextMonth() { this.setData({ month: L.shiftMonth(this.data.month, 1), batchMode: false, selectedIds: [], selectedCount: 0, allVisibleSelected: false }); this.refresh(); },\n  setFilter(e) { this.setData({ filter: e.currentTarget.dataset.filter, selectedIds: [], selectedCount: 0, allVisibleSelected: false }); this.refresh(); },\n  openPublicFilter(e) { this.setData({ tab: 'bills', filter: e.currentTarget.dataset.filter || 'all', query: '', batchMode: false, selectedIds: [], selectedCount: 0, allVisibleSelected: false }); this.refresh(); wx.pageScrollTo({ scrollTop: 0, duration: 150 }); },\n  search(e) { this.setData({ query: e.detail.value, selectedIds: [], selectedCount: 0, allVisibleSelected: false }); this.refresh(); },\n  addEntry() { this.setData({ editor: true, form: { id: '', type: 'expense', category: 'food', amount: '', note: '', spec: '', reportGroup: 'auto', reportColumn: 'auto', date: L.today() }, categories: L.categories.filter(c => c.type === 'expense') }); this.updateReportHint(); },\n  addPublicEntry(e) {\n    if (this.data.account !== 'public') return;\n    const group = e.currentTarget.dataset.group === 'drinks' ? 'drinks' : 'general';\n    this.setData({\n      editor: true,\n      form: { id: '', type: 'expense', category: group === 'drinks' ? 'coffee' : 'food', amount: '', note: '', spec: '', reportGroup: group, reportColumn: group === 'drinks' ? 'food' : 'auto', date: L.today() },\n      categories: L.categories.filter(c => c.type === 'expense')\n    });\n    this.updateReportHint();\n  },\n  editEntry(e) {\n    const r = this.book.transactions.find(t => t.id === e.currentTarget.dataset.id); if (!r) return;\n    this.setData({ editor: true, form: Object.assign({ spec: '', reportGroup: 'auto', reportColumn: 'auto' }, r, { amount: (r.amount / 100).toFixed(2) }), categories: L.categories.filter(c => c.type === r.type) }); this.updateReportHint();\n  },\n  closeEditor() { this.exportGeneration = (this.exportGeneration || 0) + 1; this.reportFiles = null; this.setData({ editor: false, budgetEditor: false, exportEditor: false }); },\n  handleBillTap(e) { if (this.data.batchMode) this.toggleSelected(e.currentTarget.dataset.id); else this.editEntry(e); },\n  toggleBatchMode() { const enabled = !this.data.batchMode; this.setData({ batchMode: enabled, selectedIds: [], selectedCount: 0, allVisibleSelected: false }); this.refresh(); },\n  toggleSelected(id) { if (!this.data.batchMode || !id) return; const selectedIds = this.data.selectedIds.includes(id) ? this.data.selectedIds.filter(value => value !== id) : this.data.selectedIds.concat(id); this.setData({ selectedIds }); this.refresh(); },\n  selectAllVisible() { if (!this.data.batchMode) return; const visibleIds = this.data.vm.groups.reduce((ids, group) => ids.concat(group.rows.map(row => row.id)), []); const selectedIds = this.data.allVisibleSelected ? [] : visibleIds; this.setData({ selectedIds }); this.refresh(); },\n  batchDelete() {\n    if (!this.data.batchMode || !this.data.selectedIds.length) return;\n    const selected = this.data.selectedIds.slice();\n    wx.showModal({ title: '删除选中的 ' + selected.length + ' 笔记录？', content: '只会删除当前账本中勾选的记录，删除后无法恢复。', confirmText: '批量删除', confirmColor: '#c16b58', success: result => {\n      if (!result.confirm) return;\n      const book = Object.assign({}, this.book, { transactions: this.book.transactions.filter(t => !selected.includes(t.id)) });\n      if (this.commit(book)) { this.setData({ batchMode: false, selectedIds: [], selectedCount: 0, allVisibleSelected: false }); this.refresh(); wx.showToast({ title: '已删除 ' + selected.length + ' 笔', icon: 'success' }); }\n    } });\n  },\n  noop() {},\n  setType(e) { const type = e.currentTarget.dataset.type; if (type === this.data.form.type) return; const categories = L.categories.filter(c => c.type === type); this.setData({ 'form.type': type, 'form.category': categories[0].id, categories }); this.updateReportHint(); },\n  setCategory(e) { this.setData({ 'form.category': e.currentTarget.dataset.id }); this.updateReportHint(); },\n  inputAmount(e) { this.setData({ 'form.amount': e.detail.value }); },\n  inputNote(e) { const patch = { 'form.note': e.detail.value }; if (this.data.account === 'public' && this.data.form.type === 'expense' && this.data.form.category === 'coffee' && this.data.form.reportGroup === 'auto' && e.detail.value !== this.data.form.note) patch['form.category'] = 'food'; this.setData(patch); this.updateReportHint(); },\n  inputSpec(e) { this.setData({ 'form.spec': e.detail.value }); },\n  updateReportHint() {\n    if (this.data.account !== 'public' || this.data.form.type !== 'expense') {\n      this.setData({ reportHint: this.data.form.type === 'income' ? '公账收入 · 不计入报销' : '', reportKind: {} });\n      return;\n    }\n    const kind = L.reportClass(this.data.form);\n    const patch = { reportHint: kind.groupName + ' · ' + kind.columnName, reportKind: kind };\n    this.setData(patch);\n  },\n  setReportGroup(e) {\n    const group = e.currentTarget.dataset.value, patch = { 'form.reportGroup': group };\n    if (group === 'drinks') patch['form.reportColumn'] = 'food';\n    else if (group === 'general' && this.data.form.reportColumn === 'food') patch['form.reportColumn'] = 'auto';\n    this.setData(patch); this.updateReportHint();\n  },\n  setReportColumn(e) { const column = e.currentTarget.dataset.value, patch = { 'form.reportColumn': column }; if (column === 'parttime') patch['form.reportGroup'] = 'general'; this.setData(patch); this.updateReportHint(); },\n  inputDate(e) { this.setData({ 'form.date': e.detail.value }); },\n  saveEntry() {\n    if (!this.data.editor) return;\n    let candidate;\n    try { candidate = L.saveEntry(this.book, this.data.form); }\n    catch (e) { wx.showToast({ title: e.message, icon: 'none' }); return; }\n    const savedAccount = this.data.account;\n    const finish = book => { if (this.commit(book)) { if (typeof wx.hideKeyboard === 'function') wx.hideKeyboard(); this.setData({ editor: false, budgetEditor: false, tab: savedAccount === 'public' ? 'bills' : 'stats', month: this.data.form.date.slice(0,7), query: '', filter: 'all', form: {}, batchMode: false, selectedIds: [], selectedCount: 0, allVisibleSelected: false }); this.refresh(); wx.pageScrollTo({ scrollTop: 0, duration: 150 }); wx.showToast({ title: savedAccount === 'public' ? '已记入公账' : '记好啦，喵～', icon: 'success' }); } };\n    finish(candidate);\n  },\n  deleteEntry() { wx.showModal({ title: '删除这笔记录？', content: '删除后无法恢复，统计数据会同步更新。', confirmText: '删除', confirmColor: '#c16b58', success: result => { if (result.confirm && this.commit(Object.assign({}, this.book, { transactions: this.book.transactions.filter(t => t.id !== this.data.form.id) }))) { this.setData({ editor: false }); wx.showToast({ title: '已删除', icon: 'success' }); } } }); },\n  openBudget() { this.setData({ budgetEditor: true, budgetInput: (this.book.budget / 100).toFixed(2) }); },\n  inputBudget(e) { this.setData({ budgetInput: e.detail.value }); },\n  saveBudget() { try { const value = String(this.data.budgetInput).trim(); const budget = /^0+(\\.0{1,2})?$/.test(value) ? 0 : L.parseAmount(value); if (this.commit(Object.assign({}, this.book, { budget }))) { this.setData({ budgetEditor: false }); wx.showToast({ title: '预算已更新', icon: 'success' }); } } catch (e) { wx.showToast({ title: e.message, icon: 'none' }); } },\n  clearBook() { wx.showModal({ title: '清空' + this.data.accountName + '账单？', content: '当前账本的全部收支记录将删除，月预算会保留。此操作无法恢复，建议先导出当前账本。另一个账本不受影响。', confirmText: '确认清空', confirmColor: '#c16b58', success: result => { if (result.confirm && this.commit(Object.assign(L.empty(), { budget: this.book.budget }))) { this.setData({ batchMode: false, selectedIds: [], selectedCount: 0 }); this.refresh(); wx.showToast({ title: '当前账本已清空', icon: 'success' }); } } }); },\n  exportBook() {\n    if (this.data.account === 'public') {\n      this.setData({ exportEditor: true, exportYear: Number(this.data.month.slice(0, 4)) }); this.prepareReports(); return;\n    }\n    this.exportCsv();\n  },\n  async prepareReports() {\n    const generation = this.exportGeneration = (this.exportGeneration || 0) + 1;\n    this.reportFiles = null;\n    const year = this.data.exportYear;\n    this.setData({ reportsReady: false, reportSummary: window.MeowReports.summary(this.book, year) });\n    try {\n      const files = await Promise.all(['general', 'drinks'].map(group => window.MeowReports.build(this.book, year, group)));\n      if (generation !== this.exportGeneration || !this.data.exportEditor) return;\n      this.reportFiles = { general: files[0], drinks: files[1] }; this.setData({ reportsReady: true });\n    } catch (_) { if (generation === this.exportGeneration) wx.showToast({ title: '报销单生成失败，请重新打开导出面板', icon: 'none' }); }\n  },\n  changeExportYear(e) {\n    const year = this.data.exportYear + Number(e.currentTarget.dataset.offset);\n    if (year < 2000 || year > 2100) return;\n    this.setData({ exportYear: year }); this.prepareReports();\n  },\n  exportReport(e) {\n    const file = this.reportFiles && this.reportFiles[e.currentTarget.dataset.group];\n    if (!this.data.reportsReady || !file || !this.data.exportEditor || this.data.account !== 'public') return;\n    const filePath = wx.env.USER_DATA_PATH + '/' + file.filename;\n    wx.getFileSystemManager().writeFile({ filePath, data: file.data, success: () => wx.shareFileMessage({ filePath, fileName: file.filename, mimeType: file.mimeType, fail: e => { if (!/cancel/.test(e.errMsg || '')) wx.showToast({ title: '导出失败，请重试', icon: 'none' }); } }) });\n  },\n  exportCsv() {\n    const filename = 'meow-ledger-' + this.data.account + '-' + L.today() + '.csv';\n    const filePath = wx.env.USER_DATA_PATH + '/' + filename;\n    wx.getFileSystemManager().writeFile({ filePath, data: L.csv(this.book, this.data.accountName), encoding: 'utf8', success: () => {\n      if (typeof wx.shareFileMessage === 'function') wx.shareFileMessage({ filePath, fileName: filename, fail: e => { if (!/cancel/.test(e.errMsg || '')) wx.showToast({ title: '请重试或检查存储空间', icon: 'none' }); } });\n      else wx.setClipboardData({ data: L.csv(this.book, this.data.accountName), success: () => wx.showToast({ title: '账单已复制，可粘贴到表格', icon: 'none' }) });\n    }, fail: () => wx.showToast({ title: '导出失败，请检查存储空间', icon: 'none' }) });\n  },\n  showPrivacy() { wx.showModal({ title: '给你安心的小账本', content: '个人消费与公账分别记账、统计和设置预算，均仅保存在当前设备的 浏览器本地存储中。公账是本机独立账本，不提供多人共享。不上传服务器，也不读取微信支付账单。清除缓存、清除网站数据或更换设备可能导致数据丢失，记得分别导出两个账本。', showCancel: false, confirmText: '知道啦', confirmColor: '#65744d' }); },\n  installHelp() { wx.showModal({ title: '把账本放到手机桌面', content: 'iPhone：用 Safari 打开本页面，点击分享按钮，再选择「添加到主屏幕」。如有「作为网页 App 打开」，请保持开启。\\n\\n添加后点桌面图标即可使用。首次联网加载完成后可离线记账；账单保存在这台设备中。', showCancel: false, confirmText: '知道啦' }); },\n  onShareAppMessage() { return { title: '喵喵账本｜把生活记成喜欢的样子', path: '/pages/index/index' }; }\n});\n"};
